import jwt
from datetime import datetime
from rest_framework_jwt.settings import api_settings
from rest_framework_jwt.views import ObtainJSONWebToken
from .models import CompanyMembership

def custom_jwt_payload_handler(user, request=None):
    payload = {
        'user_id': user.pk,
        'email': user.email,
        'exp': datetime.utcnow() + api_settings.JWT_EXPIRATION_DELTA
    }
    target_company = None
    if request and 'X-Company-ID' in request.headers:
        target_company = request.headers['X-Company-ID']
    elif request and 'active_company_id' in request.data:
        target_company = request.data['active_company_id']

    # Validate that user is an authorized member of the requested company
    if target_company and CompanyMembership.objects.filter(user=user, company_id=target_company, is_active=True).exists():
        payload['company_id'] = target_company
    else:
        payload['company_id'] = user.default_company_id
    return payload

class CustomObtainJSONWebToken(ObtainJSONWebToken):
    def post(self, request, *args, **kwargs):
        return super().post(request, *args, **kwargs)
